    tokensOut: "tokens_out",
    costMicros: "cost_micros",
    requestedAt: "requested_at",
    completedAt: "completed_at",
    callKey: "call_key",
    runAgentRunRunId: "run_agent_run_run_id",
    toolAgentToolId: "tool_agent_tool_id",
